import { test } from "node:test";
import assert from "node:assert/strict";
import { createHash } from "node:crypto";
import { readdirSync, readFileSync } from "node:fs";

// Everything here is vendored byte-for-byte from verdigris tag v0.4.0
// (see SOURCE.md). Never edit these files in spall: re-vendor from a tag and
// update SOURCE.md and these hashes together.

const css = readFileSync(new URL("./tokens.css", import.meta.url));
const sha256 = (b: Buffer) => createHash("sha256").update(b).digest("hex");

test("vendored tokens.css is byte-for-byte verdigris v0.4.0", () => {
  // Generated by verdigris build/tokens.py (WCAG-checked).
  assert.equal(sha256(css), "b0a28c2f29e9588b5fd6d7ad086f179cca2f2db3983baa27a05f8d38bbc77d12");
});

test("it defines the four themes spall's picker offers, each with the boost role", () => {
  const text = css.toString("utf8");
  assert.match(text, /^\/\* verdigris design tokens v0\.4\.0\. GENERATED/);
  const blocks = [':root, [data-theme="rust"]', '[data-theme="rust-light"]', '[data-theme="blued"]', '[data-theme="blued-light"]'];
  for (const selector of blocks) {
    const start = text.indexOf(selector);
    assert.ok(start >= 0, selector);
    const block = text.slice(start, text.indexOf("}", start));
    assert.match(block, /--vg-boost:\s*#[0-9A-F]{6};/i, `${selector} boost`);
    assert.match(block, /--vg-boost-glow:\s*#[0-9A-F]{8};/i, `${selector} boost-glow`);
  }
});

