test("vendored icons are byte-for-byte verdigris v0.4.0", () => {
  for (const [file, sha] of Object.entries(ICONS)) {
    assert.equal(sha256(readFileSync(new URL(`./${file}`, import.meta.url))), sha, file);
  }
});

test("no unrecorded files are vendored", () => {
  const svgs = (dir: string): string[] =>
    readdirSync(new URL(`./${dir}`, import.meta.url), { withFileTypes: true }).flatMap((e) =>
      e.isDirectory() ? svgs(`${dir}/${e.name}`) : e.name.endsWith(".svg") ? [`${dir}/${e.name}`] : [],
    );
  assert.deepEqual(svgs("icons").sort(), Object.keys(ICONS).sort());
});
